def test_works_bulk_joins_put_codes_and_drops_error_entries(client, httpx_mock):
    error = {"error": {"response-code": 404, "developer-message": "not found"}}
    httpx_mock.add_response(json={"bulk": [{"work": WORK}, error]})
    works = client.activities.works_bulk(ORCID_ID, [145464015, 1, 145464015])
    assert last_request(httpx_mock).url.path == f"/v3.0/{ORCID_ID}/works/145464015,1"
    assert len(works) == 1


def test_works_bulk_splits_at_100_codes(client, httpx_mock):
    httpx_mock.add_response(json={"bulk": []}, is_reusable=True)
    client.activities.works_bulk(ORCID_ID, range(1, 202))
